import { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Loader2, Hammer, CheckCircle2, FileDown, Printer, Sparkles } from "lucide-react";
import { generateQuotePDF } from "@/lib/pdf";

const API = `${process.env.REACT_APP_BACKEND_URL}/api`;

const fmtMoney = (n) =>
  `$${(Number(n) || 0).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

export default function PublicQuote() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [data, setData] = useState(null);
  const [err, setErr] = useState(false);
  const [accepting, setAccepting] = useState(false);
  const [accepted, setAccepted] = useState(false);

  useEffect(() => {
    axios.get(`${API}/public/quotes/${id}`)
      .then((r) => {
        setData(r.data);
        if (r.data?.quote?.status === "approved" || r.data?.quote?.status === "converted") {
          setAccepted(true);
        }
      })
      .catch(() => setErr(true));
  }, [id]);

  // Accept the quote → backend creates the service agreement → we send the
  // client straight to it to review & sign (then pay). One seamless link.
  const accept = async () => {
    if (!window.confirm("By clicking Accept, you approve this quote and continue to your service agreement. Continue?")) return;
    setAccepting(true);
    try {
      const r = await axios.post(`${API}/public/quotes/${id}/accept`);
      if (r.data?.agreement_id) {
        navigate(`/p/agreement/${r.data.agreement_id}`);
        return; // keep loading state during redirect
      }
      setAccepted(true);
      setAccepting(false);
    } catch (e) {
      alert(e?.response?.data?.detail || "Could not accept this quote. Please try again.");
      setAccepting(false);
    }
  };

  if (err) return <div className="min-h-screen flex items-center justify-center text-slate-500">Quote not found.</div>;
  if (!data) return <div className="min-h-screen flex items-center justify-center"><Loader2 className="w-6 h-6 animate-spin text-slate-400" /></div>;

  const { quote, business, client } = data;
  const isSoft = quote.quote_type === "soft";

  return (
    <div className="min-h-screen bg-slate-50 p-4 lg:p-10 print:p-0 print:bg-white">
      {accepting && (
        <div data-testid="preparing-agreement-overlay" className="fixed inset-0 z-50 bg-slate-900/70 backdrop-blur-sm flex items-center justify-center p-6">
          <div className="bg-white rounded-3xl shadow-2xl p-8 max-w-sm w-full text-center">
            <div className="relative w-16 h-16 mx-auto mb-4">
              <div className="absolute inset-0 rounded-full border-4 border-emerald-100" />
              <div className="absolute inset-0 rounded-full border-4 border-emerald-500 border-t-transparent animate-spin" />
              <Sparkles className="w-6 h-6 text-emerald-600 absolute inset-0 m-auto" />
            </div>
            <h3 className="font-heading text-xl font-bold text-slate-900">Preparing your agreement…</h3>
            <p className="text-sm text-slate-500 mt-2">
              We're creating your service agreement. This takes just a few seconds — please keep this page open.
            </p>
          </div>
        </div>
      )}
      <div className="max-w-3xl mx-auto">
        <div className="flex items-center justify-end gap-2 mb-4 print:hidden">
          <Button
            onClick={() => generateQuotePDF(quote, business, client)}
            variant="outline"
            className="rounded-xl"
            data-testid="public-quote-download-pdf"
          >
            <FileDown className="w-4 h-4 mr-1" /> Download PDF
          </Button>
          <Button
            onClick={() => window.print()}
            className="rounded-xl bg-blue-900 hover:bg-blue-950 text-white"
            data-testid="public-quote-print"
          >
            <Printer className="w-4 h-4 mr-1" /> Print
          </Button>
        </div>
        <Card className="bg-white border border-slate-200 shadow-sm rounded-2xl overflow-hidden print:shadow-none print:border-0">
          <div className="bg-gradient-to-br from-blue-900 to-blue-800 text-white p-6">
            <div className="flex items-start justify-between flex-wrap gap-3">
              <div>
                <div className="flex items-center gap-2 mb-1">
                  <Hammer className="w-5 h-5" />
                  <h1 className="font-heading text-2xl font-bold">{business?.business_name || "Quote"}</h1>
                </div>
                <div className="text-sm text-white/80 space-y-0.5">
                  {business?.business_email && <div>{business.business_email}</div>}
                  {business?.phone && <div>{business.phone}</div>}
                  {business?.business_address && <div>{business.business_address}</div>}
                </div>
              </div>
              <div className="text-right">
                <div className="text-3xl font-heading font-bold">QUOTE</div>
                <div className="text-sm text-white/80 mt-1">#{quote.number}</div>
                <div className="text-sm text-white/80">{new Date(quote.created_at).toLocaleDateString("en-US")}</div>
              </div>
            </div>
          </div>

          <div className="p-6 space-y-5">
            <div>
              <div className="text-xs font-bold uppercase tracking-wider text-slate-500 mb-1">Bill To</div>
              <div className="font-semibold">{client?.bill_to_company_only && client?.company ? client.company : client?.name}</div>
              {client?.address && <div className="text-sm text-slate-600">{client.address}</div>}
              {client?.email && <div className="text-sm text-slate-600">{client.email}</div>}
              {client?.phone && <div className="text-sm text-slate-600">{client.phone}</div>}
            </div>

            <div>
              <h2 className="font-heading text-xl font-bold">{quote.job_title}</h2>
              {quote.description && <p className="text-slate-700 mt-2">{quote.description}</p>}
            </div>

            {quote.scope_of_work?.length > 0 && (
              <div>
                <div className="text-xs font-bold uppercase tracking-wider text-slate-500 mb-2">Scope of Work</div>
                <ul className="list-disc ml-5 space-y-1 text-sm">
                  {quote.scope_of_work.map((s, i) => <li key={i}>{s}</li>)}
                </ul>
              </div>
            )}

            {quote.line_items?.length > 0 && (
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead className="bg-slate-100 text-left">
                    <tr>
                      <th className="p-2 font-semibold">Description</th>
                      <th className="p-2 font-semibold text-right">Qty</th>
                      <th className="p-2 font-semibold text-right">Unit</th>
                      <th className="p-2 font-semibold text-right">Price</th>
                      <th className="p-2 font-semibold text-right">Amount</th>
                    </tr>
                  </thead>
                  <tbody>
                    {quote.line_items.map((li, i) => (
                      <tr key={i} className="border-t border-slate-100">
                        <td className="p-2">{li.description}</td>
                        <td className="p-2 text-right">{li.quantity}</td>
                        <td className="p-2 text-right">{li.unit}</td>
                        <td className="p-2 text-right">{fmtMoney(li.unit_price)}</td>
                        <td className="p-2 text-right">{fmtMoney(li.amount)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}

            <div className="bg-slate-50 rounded-xl p-4 space-y-1 text-sm ml-auto max-w-xs">
              <div className="flex justify-between"><span>Subtotal</span><span>{fmtMoney(quote.subtotal)}</span></div>
              <div className="flex justify-between"><span>Tax</span><span>{fmtMoney(quote.tax_amount)}</span></div>
              <div className="flex justify-between text-lg font-bold pt-2 border-t mt-2"><span>TOTAL</span><span>{fmtMoney(quote.total)}</span></div>
              {quote.deposit_amount > 0 && <div className="flex justify-between text-emerald-700"><span>Deposit</span><span>{fmtMoney(quote.deposit_amount)}</span></div>}
            </div>

            {isSoft && (
              <div data-testid="quote-soft-disclaimer" className="rounded-xl border-2 border-amber-300 bg-amber-50 p-4 space-y-2">
                <div className="flex items-center gap-2 text-amber-800 font-bold text-sm">
                  <Sparkles className="w-4 h-4" />
                  {"Estimate / Estimado — subject to review"}
                </div>
                <p className="text-sm text-amber-800">This is a preliminary estimate based on the information provided. The final price may be adjusted once we review the work in person and confirm all details.</p>
                <p className="text-sm text-amber-800">Este es un estimado preliminar basado en la información proporcionada. El precio final puede ajustarse una vez que revisemos el trabajo en persona y confirmemos todos los detalles.</p>
              </div>
            )}

            {quote.payment_terms && (
              <div>
                <div className="text-xs font-bold uppercase tracking-wider text-slate-500 mb-1">Payment Terms</div>
                <div className="text-sm">{quote.payment_terms}</div>
              </div>
            )}
            {quote.notes && (
              <div>
                <div className="text-xs font-bold uppercase tracking-wider text-slate-500 mb-1">Notes</div>
                <div className="text-sm whitespace-pre-wrap">{quote.notes}</div>
              </div>
            )}

            {/* Accept block — clean. Accepting takes the client to the agreement to sign, then pay.
                Soft quotes (preliminary estimates) are view-only: no accept/sign/pay. */}
            {isSoft ? (
              <div data-testid="quote-soft-noaccept" className="rounded-xl border-2 border-slate-200 bg-slate-50 p-5 text-center space-y-1">
                <h3 className="font-heading text-base font-bold text-slate-800">No action needed yet · Aún no hay que hacer nada</h3>
                <p className="text-xs text-slate-600">Your contractor will review the work in person and send you a final quote you can accept, sign and pay.</p>
                <p className="text-xs text-slate-600">Tu contratista revisará el trabajo en persona y te enviará una cotización final que podrás aceptar, firmar y pagar.</p>
              </div>
            ) : accepted ? (
              <div data-testid="quote-accepted-block" className="rounded-xl border-2 border-emerald-300 bg-emerald-50 p-5 text-center space-y-3">
                <CheckCircle2 className="w-10 h-10 text-emerald-600 mx-auto" />
                <div className="font-heading text-xl font-bold text-emerald-800">Quote Accepted</div>
                <p className="text-sm text-emerald-700">
                  Next, review and sign your service agreement.
                </p>
                <Button
                  data-testid="continue-to-agreement-btn"
                  onClick={accept}
                  disabled={accepting}
                  className="w-full h-12 rounded-xl bg-emerald-600 hover:bg-emerald-700 text-white text-base font-bold"
                >
                  {accepting ? <Loader2 className="w-5 h-5 animate-spin" /> : <>Continue to Agreement &rarr;</>}
                </Button>
              </div>
            ) : (
              <div data-testid="quote-accept-block" className="rounded-xl border-2 border-blue-200 bg-blue-50/40 p-5 space-y-3 text-center">
                <h3 className="font-heading text-lg font-bold text-slate-900">Ready to move forward?</h3>
                <p className="text-xs text-slate-600">
                  Accept this quote to review and sign your service agreement, then pay your deposit — all in a few clicks.
                </p>
                <Button
                  data-testid="accept-quote-btn"
                  onClick={accept}
                  disabled={accepting}
                  className="w-full h-12 rounded-xl bg-emerald-600 hover:bg-emerald-700 text-white text-base font-bold"
                >
                  {accepting
                    ? <><Loader2 className="w-5 h-5 animate-spin mr-2" /> Preparing your agreement…</>
                    : <><CheckCircle2 className="w-5 h-5 mr-2" /> Accept this Quote</>}
                </Button>
              </div>
            )}
          </div>
        </Card>
        <div className="text-center text-xs text-slate-400 mt-4">Powered by UniTech AI</div>
      </div>
    </div>
  );
}
